python3 << 'EOF'
import zipfile
import xml.etree.ElementTree as ET

NS = {'m': 'http://schemas.openxmlformats.org/spreadsheetml/2006/main'}
z = zipfile.ZipFile('budget.xlsx')
root = ET.parse(z.open('xl/worksheets/sheet1.xml')).getroot()

def cell_value(c):
    t = c.get('t')
    if t == 'inlineStr':
        return ''.join(x.text or '' for x in c.iter('{http://schemas.openxmlformats.org/spreadsheetml/2006/main}t'))
    v = c.find('m:v', NS)
    if v is not None:
        if t == 'n':
            try: return float(v.text)
            except: return v.text
        return v.text
    return None

def col_letter(ref):
    import re
    return re.match(r'[A-Z]+', ref).group()

# Build 2D grid keyed by (row, col)
grid = {}
for row in root.findall('.//m:sheetData/m:row', NS):
    r = int(row.get('r'))
    for c in row.findall('m:c', NS):
        ref = c.get('r')
        cl = col_letter(ref)
        cn = sum((ord(ch) - 64) * (26 ** i) for i, ch in enumerate(reversed(cl)))
        grid[(r, cn)] = cell_value(c)

# Extract expense rows: rows 11-22 have amount in column C (col 3)
expenses = []
for r in range(11, 23):
    cat, item, amt = grid.get((r,1)), grid.get((r,2)), grid.get((r,3))
    if amt is not None:
        expenses.append((cat, item, float(amt)))

print("=== Expense line items (rows 11-22) ===")
for cat, item, amt in expenses:
    print(f"  {cat:<15} {item:<20} {amt:>10,.2f}")

# Total
total = sum(x[2] for x in expenses)
print(f"\nTOTAL EXPENSES (all categories): {total:,.2f}")

# Per category breakdown
from collections import OrderedDict
cats = OrderedDict()
for cat, item, amt in expenses:
    cats.setdefault(cat, 0)
    cats[cat] += amt
print("\n=== By category ===")
for cat, amt in cats.items():
    print(f"  {cat:<15} {amt:>10,.2f}  ({amt/total*100:.1f}%)")

# Cross-check with the file's own formula range SUM(C11:C22)
print(f"\nCross-check: file formula SUM(C11:C22) = {total:,.2f}")
